const files={
 main:{title:'ВНЕШНЯЯ СЕТЬ',path:'G4://PUBLIC/MAIN.TXT',body:`<p class="boot-line">&gt; ДОБРО ПОЖАЛОВАТЬ ВО ВНЕШНЮЮ СЕТЬ ЧЕТВЁРТОЙ ПЕРЕДАЧИ.</p><div class="meta"><b>КЛАСС</b><span>Частная охранная компания</span><b>ОСНОВАНА</b><span>2135</span><b>ЦЕНТР ОПЕРАЦИЙ</b><span>Крепость, Центральная Европа</span><b>СТАТУС КАНАЛА</b><span>ОТКРЫТЫЙ</span></div><h2>ОБ ОРГАНИЗАЦИИ</h2><p>Четвёртая Передача — Частная Охранная Компания, основанная в 2135 году. Задачи ЧОК широки и уже давно не ограничиваются охраной Узлов и караванов.</p><p>Четвёртая Передача готова предоставлять услуги военной поддержки, разведку на местности и в отдалённых закрытых структурах, а также исследовательские услуги, особенно в области разработки и модификации вооружения.</p><h2>НЕЗАВИСИМЫЙ СТАТУС</h2><p>Четвёртая Передача не является частью какого-либо Узла или Зелёной Зоны. Центр операций Передачи — Крепость, укреплённая база в Центральной Европе.</p>`},
 letter:{title:'ПИСЬМО ОТ БАРОНА',path:'G4://PUBLIC/DISPATCH_21-06.MSG',body:`<div class="meta"><b>ОТ</b><span>Барон Сорин Турхейм</span><b>КОМУ</b><span>Группа Бестии</span><b>ДАТА</b><span>07.10.2168</span><b>ТЕМА</b><span>Задача 21-06: Фрисити</span></div><div class="dispatch"><p>Бестия,</p><p>Разведчики из Вокс Умбра обнаружили новый Узел к северу от Крепости. Артифайсеры считают, что геопозиция Узла Фрисити может позволить найти ещё какие-то остатки проектов, существовавших на территории Объекта №6.</p><p>Нам также известно, что на Узел Фрисити нацелились силы Pharma Serpentica. Согласно текущим договорённостям мы не должны вступать с ними в боевое столкновение. Использование оружия по отношению к Pharma Serpentica — только в случае крайней необходимости.</p><p>Главная задача твоей группы — провести разведку в Узле Фрисити. Выясните, кто является главой Узла номинально, а кто на самом деле имеет авторитет среди местных жителей. Исследуйте Фрисити и прилегающую территорию.</p><p>Вероятнее всего, на территории Узла будет представитель ближайшей Зелёной Зоны — Олегуса. Любая помощь, оказанная их представителю, будет играть нам на руку.</p><p>В случае необходимости связи используйте открытый канал Четвёртой Передачи.</p><p>Уверен, ты и твоя группа меня не подведёте.<br>Жду отчёта.<br><br>Барон.</p></div>`},
 ranks:{title:'ТАБЕЛЬ О РАНГАХ',path:'G4://PUBLIC/RANKS.DB',body:`<p>&gt; ВЫВОД ОТКРЫТОЙ ВЕРСИИ КАДРОВОЙ ТАБЛИЦЫ</p><table class="rank-table"><thead><tr><th>ТИТУЛ</th><th>РАНГ</th><th>ОПИСАНИЕ</th></tr></thead><tbody><tr><td>Граф</td><td>Принцепс</td><td>Наивысший титул. Сенешаль, возглавивший Узел, Зелёную Зону или значимое поселение.</td></tr><tr><td>Барон</td><td>Сенешаль</td><td>Главнокомандующий сил Четвёртой Передачи.</td></tr><tr><td>Баронет</td><td>Галлант</td><td>Старший офицер и фактический заместитель Сенешаля.</td></tr><tr><td>Баннерет</td><td>Баллистариус</td><td>Офицер, как правило командир боевой группы.</td></tr><tr><td>Баннерет</td><td>Ферратус</td><td>Оружейник и квартирмейстер при Сенешале.</td></tr><tr><td>Баннерет</td><td>Сакратис Майорус</td><td>Главный медик Крепости и учитель новых сакратисов.</td></tr><tr><td>Рыцарь</td><td>Сагиттариус</td><td>Специалист по стрелковому и тяжёлому оружию.</td></tr><tr><td>Рыцарь</td><td>Беллатор</td><td>Специалист по оружию ближнего боя.</td></tr><tr><td>Рыцарь</td><td>Умбрус</td><td>Солдат-разведчик.</td></tr><tr><td>Рыцарь</td><td>Сакратис</td><td>Медик Четвёртой Передачи.</td></tr><tr><td>Оруженосец</td><td>Армигер</td><td>Солдат, аналог рядового.</td></tr><tr><td>Рекрут</td><td>Пробатор</td><td>Рекрут Четвёртой Передачи.</td></tr></tbody></table>`}
};
const title=document.getElementById('fileTitle'),path=document.getElementById('filePath'),content=document.getElementById('fileContent');
function openFile(id){const f=files[id];title.textContent=f.title;path.textContent=f.path;content.innerHTML=f.body;document.querySelectorAll('.file-link[data-file]').forEach(x=>x.classList.toggle('active',x.dataset.file===id));window.scrollTo({top:0,behavior:'smooth'})}
document.querySelectorAll('.file-link[data-file]').forEach(b=>b.addEventListener('click',()=>openFile(b.dataset.file)));openFile('main');
